/usr/bin/bash -lc "node - <<'NODE'
const fs = require('fs');
const plan = JSON.parse(fs.readFileSync('.exp_agent/round_01/plan.json', 'utf8'));
const completion = JSON.parse(fs.readFileSync('.exp_agent/round_01/completion.json', 'utf8'));
const expected = plan.rules.map(rule => rule.rule);
if (JSON.stringify(completion.selected_rules) "'!== JSON.stringify(expected)) throw new Error('"'selected_rules mismatch');
if (completion.entity_repairs.length "'!== plan.rules.reduce((n, rule) => n + rule.files.length, 0)) throw new Error('"'file group count mismatch');
const planned = plan.rules.flatMap(rule => rule.files.flatMap(file => file.locations.map(location => "'`${rule.rule}|${file.relative_path}|${location.line}|${location.column}`))).sort();
const reported = completion.entity_repairs.flatMap(entry => entry.locations.map(location => `${entry.rule}|${entry.relative_path}|${location.line}|${location.column}`)).sort();
if (JSON.stringify(planned) !== JSON.stringify(reported)) throw new Error('"'location set mismatch');
for (const entry of completion.entity_repairs) {
  for (const key of ['rule','relative_path','locations','entities','evidence','transformation','status']) if ("'!(key in entry)) throw new Error(`missing ${key}`);
  if (!entry.entities.length || !entry.evidence.length || !entry.transformation || entry.status !== '"'repaired') throw new Error('invalid repair entry');
}
if (completion.blocked.length || completion.unresolved_external.length) throw new Error('blocked/external not empty');
console.log('completion checks passed:', completion.entity_repairs.length, 'groups,', reported.length, 'locations');
NODE"

